impl IOI {
    /// With the required fields and groups; optional ones empty.
    #[allow(clippy::too_many_arguments, clippy::new_without_default)]
    pub fn new(
        ioiid: impl Into<CompactString>,
        ioi_trans_type: impl Into<Code<IOITransType>>,
        side: impl Into<Code<Side>>,
        ioi_qty: impl Into<Code<IOIQty>>,
    ) -> Self {
        Self {
            appl_id: None,
            appl_seq_num: None,
            appl_last_seq_num: None,
            appl_resend_flag: None,
            ioiid: ioiid.into(),
            ioi_trans_type: ioi_trans_type.into(),
            ioi_ref_id: None,
            symbol: None,
            symbol_sfx: None,
            security_id: None,
            security_id_source: None,
            security_alt_id: Vec::new(),
            product: None,
            product_complex: None,
            security_group: None,
            cfi_code: None,
            security_type: None,
            security_sub_type: None,
            maturity_month_year: None,
            maturity_date: None,
            maturity_time: None,
            settle_on_open_flag: None,
            instrmt_assignment_method: None,
            security_status: None,
            coupon_payment_date: None,
            issue_date: None,
            repo_collateral_security_type: None,
            repurchase_term: None,
            repurchase_rate: None,
            factor: None,
            credit_rating: None,
            instr_registry: None,
            country_of_issue: None,
            state_or_province_of_issue: None,
            locale_of_issue: None,
            redemption_date: None,
            strike_price: None,
            strike_currency: None,
            strike_multiplier: None,
            strike_value: None,
            opt_attribute: None,
            contract_multiplier: None,
            min_price_increment: None,
            min_price_increment_amount: None,
            unit_of_measure: None,
            unit_of_measure_qty: None,
            price_unit_of_measure: None,
            price_unit_of_measure_qty: None,
            settl_method: None,
            exercise_style: None,
            opt_pay_amount: None,
            price_quote_method: None,
            futures_valuation_method: None,
            list_method: None,
            cap_price: None,
            floor_price: None,
            put_or_call: None,
            flexible_indicator: None,
            flex_product_eligibility_indicator: None,
            time_unit: None,
            coupon_rate: None,
            security_exchange: None,
            position_limit: None,
            nt_position_limit: None,
            issuer: None,
            encoded_issuer: None,
            security_desc: None,
            encoded_security_desc: None,
            security_xml: None,
            security_xml_schema: None,
            pool: None,
            contract_settl_month: None,
            cp_program: None,
            cp_reg_type: None,
            events: Vec::new(),
            dated_date: None,
            interest_accrual_date: None,
            instrument_parties: Vec::new(),
            party_ids: Vec::new(),
            agreement_desc: None,
            agreement_id: None,
            agreement_date: None,
            agreement_currency: None,
            termination_type: None,
            start_date: None,
            end_date: None,
            delivery_type: None,
            margin_ratio: None,
            underlyings: Vec::new(),
            side: side.into(),
            qty_type: None,
            order_qty: None,
            cash_order_qty: None,
            order_percent: None,
            rounding_direction: None,
            rounding_modulus: None,
            ioi_qty: ioi_qty.into(),
            currency: None,
            stipulations: Vec::new(),
            legs: Vec::new(),
            price_type: None,
            price: None,
            valid_until_time: None,
            ioi_qlty_ind: None,
            ioi_natural_flag: None,
            ioi_qualifiers: Vec::new(),
            text: None,
            encoded_text: None,
            transact_time: None,
            url_link: None,
            routing_ids: Vec::new(),
            spread: None,
            benchmark_curve_currency: None,
            benchmark_curve_name: None,
            benchmark_curve_point: None,
            benchmark_price: None,
            benchmark_price_type: None,
            benchmark_security_id: None,
            benchmark_security_id_source: None,
            yield_type: None,
            r#yield: None,
            yield_calc_date: None,
            yield_redemption_date: None,
            yield_redemption_price: None,
            yield_redemption_price_type: None,
        }
    }
}

